from nouns_theory import T,S,L,W

def add_texts(c):
 def D(id,title,situation,speakers,lines,words,continuation):
  c.setdefault('dialogues',[]).append(dict(id=id,title=title,situation=situation,lines=[L(*line,speaker=speakers[i%2]) for i,line in enumerate(lines)],vocabulary=[W(*w) for w in words],continuation=continuation))
 D('shop',T('В магазине: свет для комнаты','У магазині: світло для кімнати','In the shop: light for a room','I butiken: ljus till ett rum'),T('Лина ищет лампу для чтения и уточняет покупку у продавца.','Ліна шукає лампу для читання й уточнює покупку у продавця.','Lina needs a reading lamp and checks what to buy with the assistant.','Lina behöver en läslampa och frågar en säljare om köpet.'),['Lina','Alex'],[
 ('Hej! Jag behöver en lampa till mitt rum.','Здравствуйте! Мне нужна лампа в мою комнату.','Вітаю! Мені потрібна лампа до моєї кімнати.','Hello! I need a lamp for my room.'),
 ('Ska den stå på ett bord?','Она будет стоять на столе?','Вона стоятиме на столі?','Will it stand on a table?'),
 ('Ja, jag läser mycket på kvällen.','Да, я много читаю вечером.','Так, я багато читаю ввечері.','Yes, I read a lot in the evening.'),
 ('Den här lampan passar bra för läsning.','Эта лампа хорошо подходит для чтения.','Ця лампа добре підходить для читання.','This lamp is good for reading.'),
 ('Vad kostar lampan?','Сколько стоит лампа?','Скільки коштує лампа?','How much is the lamp?'),
 ('Den kostar tvåhundra kronor. Du behöver också en glödlampa.','Она стоит двести крон. Тебе также нужна лампочка.','Вона коштує двісті крон. Тобі також потрібна лампочка.','It costs two hundred kronor. You also need a light bulb.'),
 ('Då tar jag lampan och en glödlampa. Har ni en påse?','Тогда беру лампу и лампочку. У вас есть пакет?','Тоді беру лампу й лампочку. У вас є пакет?','Then I’ll take the lamp and a light bulb. Do you have a bag?'),
 ('Ja. Du får ett kvitto också.','Да. Ты также получишь чек.','Так. Ти також отримаєш чек.','Yes. You get a receipt too.')],
 [('en lampa','лампа','лампа','lamp'),('en glödlampa','лампочка','лампочка','light bulb'),('ett bord','стол','стіл','table'),('en påse','пакет','пакет','bag'),('ett kvitto','чек','чек','receipt')],T('Попроси пакет и спроси цену. Замени лампу на книгу.','Попроси пакет і запитай ціну. Заміни лампу на книжку.','Ask for a bag and a price. Change the lamp to a book.','Be om en påse och fråga om priset. Byt lampan mot en bok.'))
 D('school',T('На SFI: подготовка к уроку','На SFI: підготовка до уроку','At SFI: getting ready','På sfi: före lektionen'),T('Омар пришёл на занятие без ручки и уточняет, где можно сесть.','Омар прийшов на заняття без ручки й уточнює, де сісти.','Omar arrives without a pen and asks where to sit.','Omar kommer utan penna och frågar var han kan sitta.'),['Omar','Maja'],[
 ('Ursäkta, har du en penna?','Извини, у тебя есть ручка?','Вибач, ти маєш ручку?','Excuse me, do you have a pen?'),
 ('Ja, här får du en penna.','Да, вот тебе ручка.','Так, ось тобі ручка.','Yes, here is a pen for you.'),
 ('Tack! Behöver vi en bok idag?','Спасибо! Нам сегодня нужна книга?','Дякую! Нам сьогодні потрібна книжка?','Thanks! Do we need a book today?'),
 ('Ja, boken ligger på ditt bord.','Да, книга лежит на твоём столе.','Так, книжка лежить на твоєму столі.','Yes, the book is on your table.'),
 ('Är den här stolen ledig?','Этот стул свободен?','Цей стілець вільний?','Is this chair free?'),
 ('Ja, sitt här bredvid mig.','Да, садись здесь рядом со мной.','Так, сідай тут поруч зі мною.','Yes, sit here next to me.'),
 ('Bra. Jag öppnar ett fönster. Det är varmt här.','Хорошо. Я открою окно. Здесь жарко.','Добре. Я відчиню вікно. Тут спекотно.','Good. I’ll open a window. It’s warm here.'),
 ('Tack! Nu börjar lektionen.','Спасибо! Сейчас начинается урок.','Дякую! Зараз починається урок.','Thanks! The lesson is starting now.')],
 [('en penna','ручка','ручка','pen'),('en bok','книга','книжка','book'),('en stol','стул','стілець','chair'),('ett fönster','окно','вікно','window'),('en lektion','урок','урок','lesson')],T('Попроси другую вещь и спроси, свободно ли место.','Попроси іншу річ і запитай, чи вільне місце.','Ask for another item and check if a seat is free.','Be om en annan sak och fråga om en plats är ledig.'))
 D('home',T('Дома: куда поставить стол?','Удома: куди поставити стіл?','At home: where should the table go?','Hemma: var ska bordet stå?'),T('Сара показывает квартиру другу. Они выбирают место для мебели.','Сара показує квартиру другові. Вони обирають місце для меблів.','Sara shows a friend her apartment. They choose where furniture should go.','Sara visar sin lägenhet för en vän. De väljer plats för möblerna.'),['Sara','Nils'],[
 ('Välkommen! Här är mitt kök.','Добро пожаловать! Вот моя кухня.','Ласкаво просимо! Ось моя кухня.','Welcome! Here is my kitchen.'),
 ('Vad fint! Finns det ett bord här?','Как красиво! Здесь есть стол?','Як гарно! Тут є стіл?','How nice! Is there a table here?'),
 ('Inte än. Jag köper ett bord imorgon.','Пока нет. Завтра я покупаю стол.','Ще ні. Завтра я купую стіл.','Not yet. I’m buying a table tomorrow.'),
 ('Bordet kan stå vid fönstret.','Стол можно поставить у окна.','Стіл можна поставити біля вікна.','The table can stand by the window.'),
 ('Ja. I mitt sovrum finns en säng och en lampa.','Да. В моей спальне есть кровать и лампа.','Так. У моїй спальні є ліжко й лампа.','Yes. In my bedroom there is a bed and a lamp.'),
 ('Behöver du en stol också?','Тебе ещё нужен стул?','Тобі ще потрібен стілець?','Do you need a chair too?'),
 ('Ja, men först behöver jag en soffa till vardagsrummet.','Да, но сначала мне нужен диван в гостиную.','Так, але спершу мені потрібен диван до вітальні.','Yes, but first I need a sofa for the living room.'),
 ('Då tittar vi i en möbelaffär tillsammans.','Тогда вместе посмотрим в мебельном магазине.','Тоді разом подивимося в меблевому магазині.','Then let’s look in a furniture shop together.')],
 [('ett kök','кухня','кухня','kitchen'),('ett sovrum','спальня','спальня','bedroom'),('en säng','кровать','ліжко','bed'),('en soffa','диван','диван','sofa'),('ett vardagsrum','гостиная','вітальня','living room'),('en möbelaffär','мебельный магазин','меблевий магазин','furniture shop')],T('Предложи место для лампы и скажи, какая мебель тебе нужна.','Запропонуй місце для лампи й скажи, які меблі тобі потрібні.','Suggest a place for a lamp and say what furniture you need.','Föreslå en plats för en lampa och säg vilka möbler du behöver.'))
 D('cafe',T('В кафе: обед перед уроком','У кафе: обід перед уроком','In a café: lunch before class','På kafé: lunch före lektionen'),T('Амина заказывает лёгкий обед. Продавец уточняет напиток и место.','Аміна замовляє легкий обід. Продавець уточнює напій і місце.','Amina orders a light lunch. The assistant asks about the drink and seating.','Amina beställer en lätt lunch. Personalen frågar om dryck och sittplats.'),['Amina','Kim'],[
 ('Hej! Jag vill ha en smörgås och en kopp kaffe, tack.','Здравствуйте! Я хочу бутерброд и чашку кофе, пожалуйста.','Вітаю! Я хочу бутерброд і чашку кави, будь ласка.','Hello! I’d like a sandwich and a cup of coffee, please.'),
 ('Vill du ha mjölk i kaffet?','Хочешь молока в кофе?','Хочеш молока до кави?','Would you like milk in the coffee?'),
 ('Nej tack, men gärna ett glas vatten.','Нет, спасибо, но стакан воды с удовольствием.','Ні, дякую, але склянку води залюбки.','No thanks, but I’d like a glass of water.'),
 ('Självklart. Vill du ha ett äpple också?','Конечно. Хочешь ещё яблоко?','Звісно. Хочеш ще яблуко?','Of course. Would you like an apple too?'),
 ('Ja, ett rött äpple blir bra.','Да, красное яблоко подойдёт.','Так, червоне яблуко підійде.','Yes, a red apple would be good.'),
 ('Ska du äta här?','Ты будешь есть здесь?','Ти їстимеш тут?','Will you eat here?'),
 ('Ja. Är bordet vid fönstret ledigt?','Да. Стол у окна свободен?','Так. Стіл біля вікна вільний?','Yes. Is the table by the window free?'),
 ('Ja, varsågod. Jag kommer med smörgåsen.','Да, пожалуйста. Я принесу бутерброд.','Так, будь ласка. Я принесу бутерброд.','Yes, please sit there. I’ll bring the sandwich.')],
 [('en smörgås','бутерброд','бутерброд','sandwich'),('en kopp kaffe','чашка кофе','чашка кави','cup of coffee'),('ett glas vatten','стакан воды','склянка води','glass of water'),('ett äpple','яблоко','яблуко','apple'),('mjölk','молоко','молоко','milk')],T('Закажи другой напиток и спроси о столике.','Замов інший напій і запитай про столик.','Order a different drink and ask about a table.','Beställ en annan dryck och fråga om ett bord.'))
 lines=[
 ('Leila flyttar till en lägenhet i Lund.','Лейла переезжает в квартиру в Лунде.','Лейла переїжджає до квартири в Лунді.','Leila moves into an apartment in Lund.',[('lägenhet','en lägenhet','indefinite')]),
 ('Hon öppnar dörren med en nyckel.','Она открывает дверь ключом.','Вона відчиняє двері ключем.','She opens the door with a key.',[('dörren','en dörr','definite'),('nyckel','en nyckel','indefinite')]),
 ('Lägenheten har ett kök och två rum.','В квартире есть кухня и две комнаты.','У квартирі є кухня й дві кімнати.','The apartment has a kitchen and two rooms.',[('Lägenheten','en lägenhet','definite'),('kök','ett kök','indefinite'),('rum','ett rum','plural')]),
 ('Köket är ljust.','Кухня светлая.','Кухня світла.','The kitchen is bright.',[('Köket','ett kök','definite')]),
 ('I köket finns ett fönster.','На кухне есть окно.','На кухні є вікно.','There is a window in the kitchen.',[('köket','ett kök','definite'),('fönster','ett fönster','indefinite')]),
 ('Hon ställer en kopp på ett bord.','Она ставит чашку на стол.','Вона ставить чашку на стіл.','She puts a cup on a table.',[('kopp','en kopp','indefinite'),('bord','ett bord','indefinite')]),
 ('Bordet är stort.','Стол большой.','Стіл великий.','The table is large.',[('Bordet','ett bord','definite')]),
 ('I ett rum står en säng.','В одной комнате стоит кровать.','В одній кімнаті стоїть ліжко.','There is a bed in one room.',[('rum','ett rum','indefinite'),('säng','en säng','indefinite')]),
 ('Hon behöver en lampa vid sängen.','Ей нужна лампа у кровати.','Їй потрібна лампа біля ліжка.','She needs a lamp by the bed.',[('lampa','en lampa','indefinite'),('sängen','en säng','definite')]),
 ('Hennes vän Amir kommer på besök.','Её друг Амир приходит в гости.','Її друг Амір приходить у гості.','Her friend Amir comes to visit.',[('vän','en vän','possessive'),('besök','ett besök','expression')]),
 ('De går till en affär tillsammans.','Они вместе идут в магазин.','Вони разом ідуть до магазину.','They go to a shop together.',[('affär','en affär','indefinite')]),
 ('Leila köper en lampa och två stolar.','Лейла покупает лампу и два стула.','Лейла купує лампу й два стільці.','Leila buys a lamp and two chairs.',[('lampa','en lampa','indefinite'),('stolar','en stol','plural')]),
 ('Amir bär en påse med tre äpplen.','Амир несёт пакет с тремя яблоками.','Амір несе пакет із трьома яблуками.','Amir carries a bag with three apples.',[('påse','en påse','indefinite'),('äpplen','ett äpple','plural')]),
 ('Hemma dricker de kaffe och äter ett äpple var.','Дома они пьют кофе и едят по яблоку.','Удома вони п’ють каву й їдять по яблуку.','At home they drink coffee and eat an apple each.',[('kaffe','ett kaffe','mass'),('äpple','ett äpple','indefinite')])]
 roles={'indefinite':T('неопределённая форма, один предмет','неозначена форма, один предмет','indefinite singular','obestämd singular'),'definite':T('определённая форма, известный предмет','означена форма, відомий предмет','definite singular, identifiable item','bestämd singular, identifierbar sak'),'plural':T('множественное число без en/ett','множина без en/ett','plural without en/ett','plural utan en/ett'),'possessive':T('без артикля после hennes','без артикля після hennes','no article after hennes','utan artikel efter hennes'),'expression':T('без артикля в выражении på besök','без артикля у вислові på besök','no article in fixed på besök','utan artikel i uttrycket på besök'),'mass':T('вещество без артикля; обычно kaffet','речовина без артикля; зазвичай kaffet','substance without article; normally kaffet','ämne utan artikel; vanligen kaffet')}
 c['reading']=dict(title=T('Новая квартира Лейлы','Нова квартира Лейли','Leila’s new apartment','Leilas nya lägenhet'),tip=T('Сначала слушай целиком, затем по предложениям. Выделены существительные; подписи показывают словарную пару и форму. Hon и de — уже знакомые местоимения; flyttar, har, köper — presens.','Спершу слухай цілком, потім за реченнями. Виділено іменники; підписи показують словникову пару й форму. Hon та de — уже знайомі займенники; flyttar, har, köper — presens.','Listen to the whole text, then sentence by sentence. Highlighted nouns have notes showing their word pair and form. Hon and de are familiar pronouns; flyttar, har and köper are in presens.','Lyssna först på hela texten och sedan mening för mening. Markerade substantiv har noter med ordpar och form. Hon och de är bekanta pronomen; flyttar, har och köper står i presens.'),lines=[L(s,r,u,e,annotations=[dict(form=f,role=T(*[pair+' — '+roles[role][lang] for lang in ['ru','uk','en','sv']])) for f,pair,role in annotations]) for s,r,u,e,annotations in lines],vocabulary=[W(*w) for w in [('en lägenhet','квартира','квартира','apartment'),('en nyckel','ключ','ключ','key'),('ett kök','кухня','кухня','kitchen'),('en säng','кровать','ліжко','bed'),('en affär','магазин','магазин','shop'),('ett äpple','яблоко','яблуко','apple')]])
 def writing(id,title,prompt,requirements,criteria,model,translation):c['writing'].append(dict(id='nouns-writing-v1-'+id,title=title,prompt=prompt,requirements=requirements,criteria=criteria,model=model,translation=translation))
 writing('room',T('1. Моя комната','1. Моя кімната','1. My room','1. Mitt rum'),T('Опиши свою или вымышленную комнату в 4–5 предложениях. Назови мебель и скажи, где она стоит.','Опиши свою чи вигадану кімнату в 4–5 реченнях. Назви меблі й скажи, де вони стоять.','Describe your room or an invented room in 4–5 sentences. Name furniture and say where it is.','Beskriv ditt eller ett påhittat rum med 4–5 meningar. Nämn möbler och säg var de står.'),T('I mitt rum finns …; en säng, ett bord, en lampa, en stol.','I mitt rum finns …; en säng, ett bord, en lampa, en stol.','Use I mitt rum finns …; en säng, ett bord, en lampa, en stol.','Använd I mitt rum finns …; en säng, ett bord, en lampa, en stol.'),T('Есть en- и ett-слова; новый предмет с артиклем; у каждого предложения есть глагол.','Є en- та ett-слова; новий предмет з артиклем; кожне речення має дієслово.','Include both genders; introduce items with articles; give each sentence a verb.','Ta med båda genus; presentera saker med artikel; ha verb i varje mening.'),'I mitt rum finns en säng och ett bord. Bordet står vid fönstret. Jag har en lampa. Lampan står på bordet.',T('В моей комнате есть кровать и стол. Стол стоит у окна. У меня есть лампа. Лампа стоит на столе.','У моїй кімнаті є ліжко й стіл. Стіл стоїть біля вікна. Я маю лампу. Лампа стоїть на столі.','My room has a bed and a table. The table is by the window. I have a lamp. The lamp is on the table.','Exemplet presenterar möbler och återkommer till samma bord och lampa.'))
 writing('shopping',T('2. Список покупок','2. Список покупок','2. Shopping list','2. Inköpslista'),T('Составь список из 6 покупок. Для единичных предметов укажи en/ett, для двух покупок используй число и plural. Затем напиши одну просьбу продавцу.','Склади список із 6 покупок. Для одиничних предметів указуй en/ett, для двох покупок використай число й plural. Потім напиши одне прохання продавцю.','List 6 purchases. Use en/ett for individual items and a number plus plural for two entries. Then write one request to an assistant.','Gör en lista med 6 inköp. Använd en/ett för enstaka saker och tal plus plural för två poster. Skriv sedan en fråga till en säljare.'),T('en penna, ett glas, en kopp, ett äpple, lampor, stolar; Jag vill ha …','en penna, ett glas, en kopp, ett äpple, lampor, stolar; Jag vill ha …','Useful words: en penna, ett glas, en kopp, ett äpple, lampor, stolar; Jag vill ha …','Användbara ord: en penna, ett glas, en kopp, ett äpple, lampor, stolar; Jag vill ha …'),T('Шесть позиций; род проверен по словарю; после чисел нет en/ett; просьба понятна.','Шість позицій; рід перевірено у словнику; після чисел немає en/ett; прохання зрозуміле.','Six entries; gender checked; no en/ett after numbers; a clear request.','Sex poster; genus kontrollerat; inget en/ett efter tal; en begriplig fråga.'),'En penna, ett glas, en kopp, ett äpple, två lampor, tre stolar. Jag vill ha ett glas, tack.',T('Ручка, стакан, чашка, яблоко, две лампы, три стула. Я хочу стакан, пожалуйста.','Ручка, склянка, чашка, яблуко, дві лампи, три стільці. Я хочу склянку, будь ласка.','A pen, a glass, a cup, an apple, two lamps, three chairs. I’d like a glass, please.','Exemplet har fyra singularformer, två pluralformer och en beställning.'))
 writing('kitchen',T('3. Кухня или класс','3. Кухня чи клас','3. Kitchen or classroom','3. Kök eller klassrum'),T('Выбери кухню или класс. Напиши 5 предложений, включая описание цвета или размера.','Обери кухню чи клас. Напиши 5 речень, зокрема опис кольору або розміру.','Choose a kitchen or classroom. Write 5 sentences including colour or size.','Välj ett kök eller klassrum. Skriv 5 meningar, även om färg eller storlek.'),T('Här finns …; en stor stol, ett stort bord, en röd kopp.','Här finns …; en stor stol, ett stort bord, en röd kopp.','Use Här finns …; en stor stol, ett stort bord, en röd kopp.','Använd Här finns …; en stor stol, ett stort bord, en röd kopp.'),T('Пять предложений; stor/stort и röd/rött согласованы; повтор известного предмета в определённой форме.','П’ять речень; stor/stort і röd/rött узгоджено; повтор відомого предмета в означеній формі.','Five sentences; correct stor/stort and röd/rött; use a definite form to revisit an item.','Fem meningar; rätt stor/stort och röd/rött; bestämd form när samma sak återkommer.'),'Här finns ett stort bord. Bordet står i köket. På bordet finns en röd kopp. Jag har två stolar. Köket är ljust.',T('Здесь есть большой стол. Стол стоит на кухне. На столе есть красная чашка. У меня два стула. Кухня светлая.','Тут є великий стіл. Стіл стоїть на кухні. На столі є червона чашка. Я маю два стільці. Кухня світла.','There is a large table here. The table is in the kitchen. There is a red cup on the table. I have two chairs. The kitchen is bright.','Exemplet beskriver köket med möbler, färg, storlek och antal.'))
 writing('home',T('4. Связный текст о жилье','4. Зв’язний текст про житло','4. A connected text about a home','4. En sammanhängande text om en bostad'),T('Напиши 6–8 связанных предложений о квартире или доме. Представь жильё, опиши комнаты, затем скажи, что нужно купить.','Напиши 6–8 пов’язаних речень про квартиру чи будинок. Представ житло, опиши кімнати, потім скажи, що треба купити.','Write 6–8 connected sentences about an apartment or house. Introduce the home, describe rooms and say what you need to buy.','Skriv 6–8 sammanhängande meningar om en lägenhet eller ett hus. Presentera bostaden, beskriv rummen och berätta vad du behöver köpa.'),T('Jag bor i …; den/det; ett kök, ett rum, en lägenhet, en soffa; Jag behöver …','Jag bor i …; den/det; ett kök, ett rum, en lägenhet, en soffa; Jag behöver …','Use Jag bor i …; den/det; ett kök, ett rum, en lägenhet, en soffa; Jag behöver …','Använd Jag bor i …; den/det; ett kök, ett rum, en lägenhet, en soffa; Jag behöver …'),T('Есть логическая связь; оба рода; presens; верное число; после min/mitt нет определённого окончания. Проверь по словарю, затем прочитай вслух.','Є логічний зв’язок; обидва роди; presens; правильне число; після min/mitt немає означеного закінчення. Перевір у словнику й прочитай уголос.','Check coherence, both genders, presens, number and no definite suffix after min/mitt. Consult a dictionary and read aloud.','Kontrollera samband, båda genus, presens, antal och ingen bestämd ändelse efter min/mitt. Slå upp orden och läs högt.'),'Jag bor i en lägenhet. Den har ett kök och två rum. I köket finns ett bord. Bordet är stort. Mitt sovrum har en säng. Jag behöver en lampa. Jag köper lampan imorgon.',T('Я живу в квартире. В ней кухня и две комнаты. На кухне есть стол. Стол большой. В моей спальне есть кровать. Мне нужна лампа. Я покупаю эту лампу завтра.','Я живу у квартирі. У ній кухня й дві кімнати. На кухні є стіл. Стіл великий. У моїй спальні є ліжко. Мені потрібна лампа. Я купую цю лампу завтра.','I live in an apartment. It has a kitchen and two rooms. There is a table in the kitchen. The table is large. My bedroom has a bed. I need a lamp. I am buying the lamp tomorrow.','Exemplet går från bostaden till rummen, möblerna och ett planerat inköp.'))
